const pool = global.get('pgPool');
if (!pool) return null;

// Poisson approximation: lambda = 0.05 alarms per 10s tick
if (Math.random() > 0.05) return null;

const eqps = ['LDI-01','LDI-02','LDI-05','LDI-06','LDI-09','LDI-10'];
const eqp = eqps[Math.floor(Math.random() * eqps.length)];
const codes = ['1001', '2002', '3003', '4004', '5005']; // Integer alarm codes per schema
const code = codes[Math.floor(Math.random() * codes.length)];
const logid = 'ALM-' + Date.now();
const proc = 'DF INNER';
const factory = '1';

const sql = `INSERT INTO public.ldi_alarm_log (logid, logdate, errorcode, errortime, equipmentid, factory, process) VALUES ($1, NOW(), $2, $3, $4, $5, $6)`;
const params = [logid, code, new Date().toISOString(), eqp, factory, proc];

pool.query(sql, params, (err) => {
    if (err) node.error("Alarm insert failed: " + err.message);
    else node.log("Simulated alarm inserted for " + eqp);
});

return null;
